-- G2-D candidate only. Requires the R3-B market_core schema and G2-A/G2-C candidates.
DO $$ BEGIN CREATE ROLE market_core_corporate_action_ingest NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE market_core.corporate_action_revisions (
  -- ratio_from = units before the event; ratio_to = units after the event.
  revision_id uuid PRIMARY KEY, action_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES market_core.listings(listing_id), provider_id uuid NOT NULL REFERENCES market_core.providers(provider_id), rights_policy_id uuid NOT NULL REFERENCES market_core.license_policies(rights_policy_id),
  event_type text NOT NULL CHECK (event_type IN ('SPLIT','DIVIDEND')), ex_date date NOT NULL, record_date date, payment_date date, ratio_from numeric(30,12), ratio_to numeric(30,12), dividend_amount numeric(30,12), dividend_currency char(3), source_revision text NOT NULL CHECK (source_revision ~ '^[a-f0-9]{64}$'), first_seen_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL, as_known_at timestamptz NOT NULL, supersedes_revision_id uuid REFERENCES market_core.corporate_action_revisions(revision_id), quality_flags text[] NOT NULL DEFAULT '{}',
  UNIQUE(action_id,source_revision), CHECK (first_seen_at<=ingested_at AND as_known_at<=ingested_at), CHECK ((event_type='SPLIT' AND ratio_from>0 AND ratio_to>0 AND dividend_amount IS NULL AND dividend_currency IS NULL) OR (event_type='DIVIDEND' AND dividend_amount>=0 AND dividend_currency ~ '^[A-Z]{3}$' AND ratio_from IS NULL AND ratio_to IS NULL)), CHECK (record_date IS NULL OR record_date>=ex_date), CHECK (payment_date IS NULL OR payment_date>=ex_date)
);
CREATE INDEX corporate_action_pit_idx ON market_core.corporate_action_revisions(listing_id,ex_date,as_known_at DESC);
CREATE OR REPLACE FUNCTION market_core.prevent_corporate_action_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'corporate action revisions are append-only'; END $$;
CREATE TRIGGER corporate_action_append_only BEFORE UPDATE OR DELETE ON market_core.corporate_action_revisions FOR EACH ROW EXECUTE FUNCTION market_core.prevent_corporate_action_mutation();
ALTER TABLE market_core.corporate_action_revisions ENABLE ROW LEVEL SECURITY; ALTER TABLE market_core.corporate_action_revisions FORCE ROW LEVEL SECURITY; REVOKE ALL ON market_core.corporate_action_revisions FROM PUBLIC; GRANT USAGE ON SCHEMA market_core TO market_core_corporate_action_ingest; GRANT INSERT ON market_core.corporate_action_revisions TO market_core_corporate_action_ingest; GRANT SELECT ON market_core.corporate_action_revisions TO market_core_reader;
CREATE POLICY corporate_action_reader ON market_core.corporate_action_revisions FOR SELECT TO market_core_reader USING (current_user='market_core_reader'); CREATE POLICY corporate_action_ingest ON market_core.corporate_action_revisions FOR INSERT TO market_core_corporate_action_ingest WITH CHECK (current_user='market_core_corporate_action_ingest');
CREATE OR REPLACE FUNCTION market_core.read_corporate_actions_pit(p_listing_id uuid,p_start_date date,p_end_date date,p_cutoff timestamptz) RETURNS TABLE(action_id uuid,listing_id uuid,provider_id uuid,rights_policy_id uuid,status text,revision_id uuid,event_type text,ex_date date,record_date date,payment_date date,ratio_from numeric,ratio_to numeric,dividend_amount numeric,dividend_currency text,source_revision text,first_seen_at timestamptz,ingested_at timestamptz,as_known_at timestamptz,quality_flags text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=market_core,pg_catalog AS $$
 WITH ranked AS (SELECT c.*,row_number() OVER(PARTITION BY c.action_id ORDER BY c.as_known_at DESC,c.ingested_at DESC,c.revision_id DESC) rn FROM market_core.corporate_action_revisions c JOIN market_core.listings l ON l.listing_id=c.listing_id WHERE current_setting('role')='market_core_reader' AND c.listing_id=p_listing_id AND c.first_seen_at<=p_cutoff AND c.ingested_at<=p_cutoff AND c.as_known_at<=p_cutoff), selected AS (SELECT c.* FROM ranked c WHERE c.rn=1 AND c.ex_date BETWEEN p_start_date AND p_end_date AND c.ex_date>= (SELECT valid_from FROM market_core.listings WHERE listing_id=c.listing_id) AND c.ex_date < COALESCE((SELECT valid_to FROM market_core.listings WHERE listing_id=c.listing_id), 'infinity'::date))
 SELECT CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.action_id ELSE NULL END,c.listing_id,c.provider_id,c.rights_policy_id,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN 'AVAILABLE' ELSE 'LICENSE_BLOCKED' END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.revision_id ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.event_type ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.ex_date ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.record_date ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.payment_date ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.ratio_from ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.ratio_to ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.dividend_amount ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.dividend_currency::text ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.source_revision ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.first_seen_at ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.ingested_at ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.as_known_at ELSE NULL END,CASE WHEN lp.display_allowed AND lp.cache_allowed AND (lp.retention_until IS NULL OR lp.retention_until>statement_timestamp()) THEN c.quality_flags ELSE ARRAY[]::text[] END FROM selected c JOIN market_core.license_policies lp ON lp.rights_policy_id=c.rights_policy_id;
$$;
REVOKE ALL ON market_core.corporate_action_revisions FROM market_core_reader; REVOKE ALL ON FUNCTION market_core.read_corporate_actions_pit(uuid,date,date,timestamptz) FROM PUBLIC; GRANT EXECUTE ON FUNCTION market_core.read_corporate_actions_pit(uuid,date,date,timestamptz) TO market_core_reader;
